use crate::{editor::{Editor,Action},scene::Scene};
use session_rust::{Point,Line,Plane,Xform,Geometry};
use std::rc::Rc;
fn editor()->Editor{let mut e=Editor::default();e.apply(Action::Close).unwrap();e}
fn command(e:&mut Editor,line:&str)->Result<(),String>{let action=if let Some(action)=e.tool_line(line){action.map_err(str::to_owned)?}else{let crate::commands::Command::Editor(action)=crate::commands::parse(line)?else{return Err("Editor command".into())};action};e.apply(action).map_err(str::to_owned)?;Ok(())}
#[test]
fn groups_and_graphs_preserve_world_originals_history_and_archive(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w1,0,0").unwrap();command(&mut e,"Line w0,1,0 w1,1,0").unwrap();
    let ids=e.scene.lines().iter().map(|r|r.id).collect::<Vec<_>>();let a=e.scene.lines()[0].prepared.source.clone();let b=e.scene.lines()[1].prepared.source.clone();
    for (i,id) in ids.iter().enumerate(){e.scene.place_following(*id,Xform::translation(1000000000.125,20.+i as f64,3.)).unwrap();}
    let poses=ids.iter().map(|id|e.scene.placement(*id).unwrap().m).collect::<Vec<_>>();e.select_objects(ids.clone(),false);let n=e.scenes().count();command(&mut e,"Add Group timber").unwrap();assert_eq!(e.scenes().count(),n+1);assert_eq!(e.scene.groups.len(),1);
    e.select_objects([ids[0]],false);let mut selected=e.selected_objects();selected.sort_unstable_by_key(|id|id.value());assert_eq!(selected,ids);for (id,m) in ids.iter().zip(&poses){assert_eq!(e.scene.placement(*id).unwrap().m,*m)}assert!(Rc::ptr_eq(&a,&e.scene.lines()[0].prepared.source));assert!(Rc::ptr_eq(&b,&e.scene.lines()[1].prepared.source));
    command(&mut e,"Add Edge").unwrap();let key=e.scene.forest.documents[0].key;let graph=e.scene.graphs[&key].to_proto();assert_eq!(graph.edges.len(),1);let n=e.scenes().count();assert!(command(&mut e,"Add Edge").is_err());assert_eq!(e.scenes().count(),n);
    command(&mut e,"Undo").unwrap();assert!(e.scene.graphs.is_empty());assert_eq!(e.scene.groups.len(),1);assert!(command(&mut e,"Add Group timber").is_err());command(&mut e,"Redo").unwrap();assert_eq!(e.scene.graphs[&key].to_proto().edges,graph.edges);
    let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut restored=Scene::empty();crate::scene_document::open(&mut restored,&bytes).unwrap();assert_eq!(restored.groups.len(),1);let doc=&restored.forest.documents[0];assert_eq!(doc.header.as_ref().unwrap().header.graph.as_ref().unwrap().edges.len(),1);
    for(row,pose)in restored.lines().iter().zip(&poses){assert_eq!(row.model.m,*pose)}e.apply(Action::Close).unwrap();e.scene=restored;e.select_objects([e.scene.lines()[0].id],false);assert_eq!(e.selected_objects().len(),2);assert!(command(&mut e,"Add Edge").is_err());
    let mut panel=crate::tree_panel::TreePanel::default();panel.refresh(&e.scene,e.selected_objects());assert_eq!(panel.graph.len(),1);assert_eq!(panel.graph[0].3,"");
}
#[test]
fn plane_sources_are_wire_only_exactly_saved_and_used_as_trim_cutters(){
    let mut e=editor();let plane=Rc::new(Plane::yz_plane());let _=plane.guid();let before=plane.to_proto();let cut=crate::plane_original::insert(&mut e.scene,plane.clone()).unwrap();let row=&e.scene.objects()[0];assert!(row.mesh.indices().is_empty());assert_eq!(row.mesh.parts.edges.len(),7);assert!(crate::source_cut::as_plane(&crate::source_edit::original(&e.scene,cut).unwrap()).is_some());
    let surface=Rc::new(crate::patch_geometry::patch(&[Point::new(-2.,-2.,0.),Point::new(2.,-2.,0.),Point::new(2.,2.,0.),Point::new(-2.,2.,0.)]).unwrap());let target=e.scene.insert_surface(surface.clone()).unwrap();e.select_objects([target],false);command(&mut e,"Trim").unwrap();e.apply(Action::TrimPick(Some(cut))).unwrap();command(&mut e,"Trim").unwrap();assert!(e.trimming_parts());assert_eq!(e.trim.as_ref().unwrap().cuts[0].parts.count(),2);
    let mut draft=e.trim.take().unwrap();assert!(draft.remove(0,0).unwrap());assert!(draft.remove(0,1).is_err());draft.refresh_preview(&e.scene).unwrap();assert!(Rc::ptr_eq(&surface,&e.scene.objects().iter().find(|r|r.id==target).unwrap().surface.as_ref().unwrap().source));assert!(draft.preview.as_ref().unwrap().objects().iter().find(|r|r.id==target).unwrap().cad.is_some());e.trim=Some(draft);command(&mut e,"Escape").unwrap();assert!(e.scene.objects().iter().find(|r|r.id==target).unwrap().surface.is_some());
    command(&mut e,"Trim").unwrap();e.apply(Action::TrimPick(Some(cut))).unwrap();command(&mut e,"Trim").unwrap();let mut draft=e.trim.take().unwrap();draft.remove(0,0).unwrap();e.trim=Some(draft);let n=e.scenes().count();command(&mut e,"Trim").unwrap();assert_eq!(e.scenes().count(),n+1);let row=e.scene.objects().iter().find(|r|r.id==target).unwrap();assert_eq!(row.cad.as_ref().unwrap().source.face_count(),1);assert!((crate::measure_area::compute_area(&Geometry::BRep(row.cad.as_ref().unwrap().source.clone()),&Xform::identity(),None).unwrap()-8.).abs()<1e-5);
    let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut restored=Scene::empty();crate::scene_document::open(&mut restored,&bytes).unwrap();let original=restored.objects().iter().find_map(|r|match &r.original{Some(Geometry::Plane(p))=>Some(p),_=>None}).unwrap();assert_eq!(original.to_proto(),before);assert_eq!(plane.to_proto(),before);command(&mut e,"Undo").unwrap();assert!(Rc::ptr_eq(&surface,&e.scene.objects().iter().find(|r|r.id==target).unwrap().surface.as_ref().unwrap().source));command(&mut e,"Redo").unwrap();assert!(e.scene.objects().iter().find(|r|r.id==target).unwrap().cad.is_some());
}
#[test]
fn trim_preview_rejects_changed_originals_without_creating_history(){
    let mut e=editor();let id=e.scene.insert_line(crate::stroke::PreparedLine::new(Rc::new(Line::new(-3.,0.,0.,3.,0.,0.))).unwrap()).unwrap();let mut cutters=Vec::new();for x in[-1.,1.]{let plane=Rc::new(Plane::from_point_normal(Point::new(x,0.,0.),session_rust::Vector::x_axis(),None));cutters.push(crate::plane_original::insert(&mut e.scene,plane).unwrap());}e.select_objects([id],false);command(&mut e,"Trim").unwrap();for cut in cutters{e.apply(Action::TrimPick(Some(cut))).unwrap();}command(&mut e,"Trim").unwrap();let mut draft=e.trim.take().unwrap();assert_eq!(draft.cuts[0].parts.count(),3);assert!(!draft.remove(0,1).unwrap());draft.refresh_preview(&e.scene).unwrap();assert_eq!(e.scene.lines().len(),1);assert_eq!(draft.preview.as_ref().unwrap().paths().len()+draft.preview.as_ref().unwrap().lines().len(),2);let n=e.scenes().count();e.scene.place_following(id,Xform::translation(1.,0.,0.)).unwrap();assert!(draft.prepared_edits(&e.scene).is_err());e.trim=Some(draft);assert!(command(&mut e,"Trim").is_err());assert!(e.trim.is_none());assert_eq!(e.scenes().count(),n);assert_eq!(e.scene.lines().len(),1);
}
#[test]
fn lasso_uses_physical_spacing_whole_originals_and_retains_selection_on_a_miss(){
    let mut e=editor();command(&mut e,"Point w-1,0,0").unwrap();command(&mut e,"Point w1,0,0").unwrap();command(&mut e,"View Top").unwrap();let ids=e.scene.points().iter().map(|r|r.id).collect::<Vec<_>>();e.select_objects([ids[1]],false);let n=e.scenes().count();
    for text in["Select Lasso","selectlasso"]{command(&mut e,text).unwrap();command(&mut e,"Escape").unwrap();}assert!(crate::commands::parse("Select Lasso x").is_err());command(&mut e,"Select Lasso").unwrap();let point=e.scene.points()[0].point();let p=crate::rect_select::screen(&e.camera.view_projection().m,[point[0],point[1],point[2]],[640.,480.]).unwrap();let corners=[[p[0]-15.,p[1]-15.],[p[0]+15.,p[1]-15.],[p[0]+15.,p[1]+15.],[p[0]-15.,p[1]+15.]];
    e.apply(Action::LassoPress{at:corners[0],size:[640.,480.],density:2.,pointer:7}).unwrap();for at in &corners[1..]{e.apply(Action::LassoMove{at:*at,pointer:7}).unwrap();}assert_eq!(e.lasso.as_ref().unwrap().points[0],(corners[0][0]*2.,corners[0][1]*2.));e.apply(Action::LassoRelease{at:corners[0],pointer:7,add:true,remove:false}).unwrap();let mut selected=e.selected_objects();selected.sort_unstable_by_key(|id|id.value());assert_eq!(selected,ids);assert!(e.lasso.is_none());assert_eq!(e.scenes().count(),n);
    command(&mut e,"Select Lasso").unwrap();e.apply(Action::LassoPress{at:[5.,5.],size:[640.,480.],density:1.,pointer:9}).unwrap();for at in[[20.,5.],[20.,20.],[5.,20.]]{e.apply(Action::LassoMove{at,pointer:9}).unwrap();}assert!(e.apply(Action::LassoRelease{at:[5.,5.],pointer:9,add:false,remove:false}).is_err());assert!(e.lasso.is_some());let mut selected=e.selected_objects();selected.sort_unstable_by_key(|id|id.value());assert_eq!(selected,ids);command(&mut e,"View Front").unwrap();assert!(e.lasso.is_some());command(&mut e,"Text tree").unwrap();assert!(e.lasso.is_none());assert!(e.draft.as_ref().unwrap().text.is_some());
}
#[test]
fn appended_group_archives_keep_independent_graphs_and_delete_cleans_only_its_document(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w1,0,0").unwrap();command(&mut e,"Line w0,1,0 w1,1,0").unwrap();command(&mut e,"Select All").unwrap();command(&mut e,"Add Group pair").unwrap();command(&mut e,"Add Edge").unwrap();let mut candidate=e.scene.clone();candidate.append_document(&e.scene,"",&Xform::identity(),0.).unwrap();e.apply(Action::Adopt{scene:Box::new(candidate),replace:false}).unwrap();assert_eq!(e.scene.groups.len(),2);assert_eq!(e.scene.graphs.len(),2);assert_eq!(e.scene.lines().len(),4);
    let first=e.scene.lines()[0].id;e.select_objects([first],false);assert_eq!(e.selected_objects().len(),2);assert!(command(&mut e,"Add Edge").is_err());command(&mut e,"Delete").unwrap();assert_eq!(e.scene.lines().len(),2);let counts=e.scene.graphs.values().map(|g|g.to_proto().edges.len()).collect::<Vec<_>>();assert!(counts.contains(&0)&&counts.contains(&1));command(&mut e,"Undo").unwrap();assert_eq!(e.scene.lines().len(),4);assert!(e.scene.graphs.values().all(|g|g.to_proto().edges.len()==1));let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut restored=Scene::empty();crate::scene_document::open(&mut restored,&bytes).unwrap();assert_eq!(restored.groups.len(),2);assert_eq!(restored.forest.documents.len(),2);for doc in &restored.forest.documents{assert_eq!(doc.header.as_ref().unwrap().header.graph.as_ref().unwrap().edges.len(),1)}
}
#[test]
fn extension_errors_mark_the_original_world_endpoint_and_escape_releases_guides(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w1,0,0").unwrap();let id=e.scene.lines()[0].id;e.scene.place_following(id,Xform::translation(10.,20.,30.)).unwrap();let source=e.scene.lines()[0].prepared.source.clone();command(&mut e,"Extend Distance 1").unwrap();let draft=e.draft.as_mut().unwrap().extend.as_mut().unwrap();draft.error="No crossing".into();draft.last=Some((id,crate::extend_reach::End::End));draft.hover=None;let overlay=e.guide_overlay();assert_eq!(overlay.label,Some(([11.,20.,30.],"No crossing".into())));assert_eq!(overlay.marks.len(),1);assert!(overlay.segments.is_empty());let n=e.scenes().count();command(&mut e,"Escape").unwrap();assert_eq!(e.guide_overlay(),Default::default());assert_eq!(e.scenes().count(),n);assert!(Rc::ptr_eq(&source,&e.scene.lines()[0].prepared.source));
}

#[test]
fn groups_keep_text_membership_and_original_words_through_save_open(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w1,0,0").unwrap();command(&mut e,"Text beam").unwrap();command(&mut e,"w0,1,0").unwrap();command(&mut e,"Select All").unwrap();assert_eq!(e.selected_objects().len(),2);command(&mut e,"Add Group labelled").unwrap();let text=e.scene.texts()[0].prepared.source.clone();e.select_objects([e.scene.lines()[0].id],false);assert_eq!(e.selected_objects().len(),2);let saved=crate::scene_archive::save(&e.scene).unwrap();let mut opened=Scene::empty();crate::scene_document::open(&mut opened,&saved).unwrap();assert_eq!(opened.texts()[0].prepared.source.label.text,"beam");assert_eq!(opened.groups.len(),1);e.scene=opened;e.select_objects([e.scene.lines()[0].id],false);assert_eq!(e.selected_objects().len(),2);assert_eq!(text.label.text,"beam");
}

#[test]
fn cancelling_pointer_drag_and_touch_view_controls_keep_a_completed_measurement(){
    let mut e=editor();command(&mut e,"Measure Distance w0,0,0 w3,4,0").unwrap();let mark=e.mark.clone();let n=e.scenes().count();e.apply(Action::CanvasCancel).unwrap();assert_eq!(e.mark,mark);e.apply(Action::Touch(vec![Action::Orbit(0.2,0.1),Action::Zoom(1.2),Action::Pan(0.1,0.)])).unwrap();assert_eq!(e.mark,mark);assert_eq!(e.scenes().count(),n);command(&mut e,"Escape").unwrap();assert!(e.mark.is_none());
}
